import{z as n,x as A,o as E,c as i,q as B,j as s,D as e,d as o,s as p,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"循环流缓冲","description":"","frontmatter":{"title":"循环流缓冲","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/loop-stream-buffer.md","filePath":"cs/loop-stream-buffer.md","lastUpdated":1791413859000}'),c={name:"cs/loop-stream-buffer.md"};function d(u,a,D,h,S,m){const r=A("Mermaid");return E(),i("div",null,[a[2]||(a[2]=B('<h1 id="循环流缓冲" tabindex="-1">循环流缓冲 <a class="header-anchor" href="#循环流缓冲" aria-label="Permalink to &quot;循环流缓冲&quot;">​</a></h1><div class="epigraph"><p>一旦认出循环体已经全部译码进一小块缓冲，取指单元可以休眠：uop 从缓冲循环供给，直到退出分支被预测为离开。</p><footer>—— 据 Intel 对 Loop Stream Detector 的公开描述；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/uop-cache">上一课</a>用按 IP 索引的 uop cache 绕过译码器，每拍仍要做标签比较、仍可能跨行。<a href="/cs/loop-predictor">循环预测</a>已经能猜何时离开。本课不重讲 DSB 填入。缺口是把<strong>足够小的循环锁定在更浅的流缓冲</strong>，连 uop cache 的查找都关掉。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>科学计算与多媒体里，十几到几十 uop 的循环会跑百万次。uop cache 命中已经便宜，但取指流水、BTB 读口、分支预测查表仍在跳。缺口不是更大的 uop cache，而是<strong>检测「循环体已完整驻留」后切换到从 LSB 顺序弹出 uop</strong>，退出才回到普通前端。</p><p><span class="marginnote">Intel Core 起的 LSD（Loop Stream Detector）有 uop 数上限；体太大、含过多分支或调用则不锁定。这是功耗与前端端口的交易，不是新的 ISA 循环指令。</span></p><p><span class="marginnote">可以类比把常做的五步体操动作背进肌肉记忆：背熟之后，不用每遍都翻教材（取指、译码）照着比划，直接凭记忆连做一百遍；直到口令说「换动作」（预测退出）才重新翻书。省的不只是翻书时间，更是「翻书」这件事本身的力气。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>前端统计连续向后分支且目标落在近期已译码窗口内。若循环体 uop 数 ≤ 缓冲容量、且满足「无调用、间接可预测」等实现限制，把该体复制进 LSB，置锁定。供给：每拍从 LSB 取 \\(D\\) 个 uop，IP 在体内绕回。循环预测器说「这一次退出」则解锁，从退出目标重新走 BTB/uop cache。</p>',9)),(E(),s(l,null,{default:e(()=>[p(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20DET%5B%22%E6%A3%80%E5%87%BA%E7%9F%AD%E5%BE%AA%E7%8E%AF%E4%BD%93%22%5D%20--%3E%20LOCK%5B%22%E5%A1%AB%E5%85%A5%20LSB%20%E5%B9%B6%E9%94%81%E5%AE%9A%22%5D%0A%20%20LOCK%20--%3E%20POP%5B%22%E4%BB%8E%20LSB%20%E5%BC%B9%20uop%22%5D%0A%20%20POP%20--%3E%20REN%5B%22%E9%87%8D%E5%91%BD%E5%90%8D%22%5D%0A%20%20EXIT%5B%22%E9%A2%84%E6%B5%8B%E9%80%80%E5%87%BA%22%5D%20--%3E%20UNL%5B%22%E8%A7%A3%E9%94%81%EF%BC%8C%E6%8C%89%E7%9B%AE%E6%A0%87%E9%87%8D%E5%8F%96%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[o("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"锁定期间前端各部件谁在干活、谁在休息，值得拆开看：LSB 直接供 uop，一整条取指译码链路被门控休眠。",-1)),(E(),s(l,null,{default:e(()=>[p(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20LK%5B%22%E5%BE%AA%E7%8E%AF%E4%BD%93%E5%B7%B2%E9%94%81%E5%AE%9A%E8%BF%9B%20LSB%22%5D%20--%3E%20P%5B%22%E6%AF%8F%E6%8B%8D%E4%BB%8E%20LSB%20%E9%A1%BA%E5%BA%8F%E5%BC%B9%E5%87%BA%20uop%22%5D%0A%20%20P%20--%3E%20RN%5B%22%E9%87%8D%E5%91%BD%E5%90%8D%20%2F%20%E5%88%86%E9%85%8D%22%5D%0A%20%20OFF%5B%22%E8%A2%AB%E9%97%A8%E6%8E%A7%E4%BC%91%E7%9C%A0%E7%9A%84%E9%83%A8%E4%BB%B6%22%5D%20--%3E%20S1%5B%22I-cache%20%E5%8F%96%E6%8C%87%22%5D%0A%20%20OFF%20--%3E%20S2%5B%22%E8%AF%91%E7%A0%81%E5%99%A8%22%5D%0A%20%20OFF%20--%3E%20S3%5B%22BTB%20%E4%B8%8E%E9%83%A8%E5%88%86%E9%A2%84%E6%B5%8B%E5%99%A8%E8%AF%BB%E5%8F%A3%22%5D%0A%20%20P%20--%3E%20E%5B%22%E5%89%8D%E7%AB%AF%E5%8A%9F%E8%80%97%E5%A4%A7%E9%99%8D%EF%BC%8C%E4%BE%9B%E7%BB%99%E4%B8%8D%E5%86%8D%E5%8F%97%E8%A1%8C%E5%AF%B9%E9%BD%90%E6%89%93%E6%96%AD%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<p><span class="marginnote">初学者容易以为 LSB 是架构状态、程序能感觉到它。实际它纯属微结构优化：自修改代码、异常、误预测都会解锁冲刷，架构层面什么都没变——这也是为什么同一份程序在不同核上是否用 LSD 都完全合法。</span></p><p>功耗：I-cache、uop cache、相当一部分预测器读口可以门控。带宽：LSB 的端口按重命名宽度设计，不再被 cache 行对齐打断。与<a href="/cs/loop-predictor">循环器</a> 的配合：行程 \\(N\\) 决定何时解锁；LSB 本身不学 \\(N\\)。</p><p><span class="marginnote">数字实例：一个 20 uop 的小循环跑 100 万次。普通前端每遍都要查 I-cache、uop cache、BTB，加起来约 2000 万次查表；LSB 锁定后这些查找几乎归零——对服务长热循环的代码，省下的前端功耗相当可观，这也是 LSD 的首要动机。</span></p><p>自修改或 SMC 仍要打破锁定。异常与误预测同样解锁并冲刷——LSB 不是架构状态。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把软件展开后的巨循环硬塞进 LSB。也不把 GPU 的循环缓冲、DSP 的零开销循环指令当成同一结构：那些是 ISA 可见的。宏融合会改变「几条宏指令对应几个 uop」，影响能否装进容量，下一课才讲融合。</p><p>后课默认：短热循环可以在 uop cache 之下再短一截供给路径。把相邻宏指令合成更少 uop，是另一条减前端压力的路。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LSB 锁定短循环的 uop 流，让取指与部分预测器休眠。</li><li>容量与分支限制决定能否锁定；退出靠循环预测。</li><li>减少 uop 条数的融合是下一课。</li><li>出处：Intel 优化参考手册中的 LSD；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',9))])}const _=n(c,[["render",d]]);export{L as __pageData,_ as default};
